solution.solution.cpp:
#include <cstdint>
#include <optional>
#include <vector>

struct Header
{
    std::uint8_t version;
    std::uint8_t type;
    std::uint16_t length;
    std::uint32_t sequence;
    std::uint16_t checksum;
};

std::uint16_t internetChecksum(const std::vector<std::uint8_t>& data)
{
    std::uint32_t sum{ 0 };
    for (std::size_t i{ 0 }; i < data.size(); i += 2)
    {
        const std::uint32_t word{ (static_cast<std::uint32_t>(data[i]) << 8) | (i + 1 < data.size() ? data[i + 1] : 0u) };
        sum += word;
        sum = (sum & 0xFFFF) + (sum >> 16);
    }
    return static_cast<std::uint16_t>(~sum & 0xFFFF);
}

std::vector<std::uint8_t> pack(Header h, const std::vector<std::uint8_t>& payload)
{
    const auto length{ static_cast<std::uint16_t>(10 + payload.size()) };
    std::vector<std::uint8_t> out{
        static_cast<std::uint8_t>(((h.version & 0x0F) << 4) | (h.type & 0x0F)), 0,
        static_cast<std::uint8_t>(length >> 8), static_cast<std::uint8_t>(length),
        static_cast<std::uint8_t>(h.sequence >> 24), static_cast<std::uint8_t>(h.sequence >> 16),
        static_cast<std::uint8_t>(h.sequence >> 8), static_cast<std::uint8_t>(h.sequence),
        0, 0 };
    out.insert(out.end(), payload.begin(), payload.end());
    const std::uint16_t sum{ internetChecksum(out) };
    out[8] = static_cast<std::uint8_t>(sum >> 8);
    out[9] = static_cast<std::uint8_t>(sum);
    return out;
}

std::optional<Header> unpack(const std::vector<std::uint8_t>& p, std::vector<std::uint8_t>& payload)
{
    if (p.size() < 10 || p[1] != 0) return std::nullopt;
    Header h{};
    h.version = static_cast<std::uint8_t>(p[0] >> 4);
    h.type = static_cast<std::uint8_t>(p[0] & 0x0F);
    h.length = static_cast<std::uint16_t>((p[2] << 8) | p[3]);
    h.sequence = (static_cast<std::uint32_t>(p[4]) << 24) | (p[5] << 16) | (p[6] << 8) | p[7];
    h.checksum = static_cast<std::uint16_t>((p[8] << 8) | p[9]);
    if (h.length != p.size() || internetChecksum(p) != 0) return std::nullopt;
    payload.assign(p.begin() + 10, p.end());
    return h;
}

unitTests:
using Bytes = std::vector<std::uint8_t>;
TEST("the RFC 1071 example") {
    CHECK_EQ(internetChecksum({ 0x00, 0x01, 0xF2, 0x03, 0xF4, 0xF5, 0xF6, 0xF7 }), 0x220D);
    CHECK_EQ(internetChecksum({}), 0xFFFF);
    CHECK_EQ(internetChecksum({ 0x01 }), 0xFEFF);
}
TEST("packing") {
    const Bytes p{ pack({ 2, 5, 0, 0x01020304, 0 }, { 'h', 'i' }) };
    CHECK_EQ(p.size(), 12u);
    CHECK_EQ(p[0], 0x25);
    CHECK_EQ(p[1], 0);
    CHECK_EQ(p[2], 0); CHECK_EQ(p[3], 12);
    CHECK(p[4] == 1 && p[5] == 2 && p[6] == 3 && p[7] == 4);
    CHECK_EQ(internetChecksum(p), 0);
}
TEST("unpacking") {
    Bytes payload;
    const auto h{ unpack(pack({ 15, 9, 0, 0xDEADBEEF, 0 }, { 1, 2, 3 }), payload) };
    CHECK(h.has_value());
    if (h) { CHECK_EQ(h->version, 15); CHECK_EQ(h->type, 9); CHECK_EQ(h->sequence, 0xDEADBEEFu); CHECK_EQ(h->length, 13); }
    CHECK(payload == (Bytes{ 1, 2, 3 }));
}
TEST("damaged packets") {
    Bytes payload;
    Bytes p{ pack({ 1, 1, 0, 7, 0 }, { 'a', 'b', 'c' }) };
    Bytes flipped{ p }; flipped[11] ^= 0x01;
    CHECK(!unpack(flipped, payload).has_value());
    Bytes truncated{ p }; truncated.pop_back();
    CHECK(!unpack(truncated, payload).has_value());
    Bytes reserved{ p }; reserved[1] = 1;
    CHECK(!unpack(reserved, payload).has_value());
    CHECK(!unpack(Bytes{ 1, 2, 3 }, payload).has_value());
}

